\begin{align*} \text{proj}_{\mathbf{w}} \mathbf{v} &= \frac{\mathbf{v} \cdot \mathbf{w}}{\|\mathbf{w}\|^2} \mathbf{w} \\ &= \frac{\begin{pmatrix} x \\ \frac{5}{2} x + 4 \end{pmatrix} \cdot \mathbf{w}}{\|\mathbf{w}\|^2} \mathbf{w} \\ &= \frac{x w_1 + \left( \frac{5}{2} x + 4 \right) w_2}{\|\mathbf{w}\|^2} \mathbf{w} \\ &= \frac{x (w_1 + \frac{5}{2} w_2) + 4 w_2}{\|\mathbf{w}\|^2} \mathbf{w} \\ &= \begin{pmatrix} x (w_1 + \frac{5}{2} w_2) + 4 w_2 \\ \frac{5}{2} x (w_1 + \frac{5}{2} w_2) + 4 w_2 \end{pmatrix} \frac{1}{\|\mathbf{w}\|^2} \mathbf{w} \\ &= \begin{pmatrix} x (w_1 + \frac{5}{2} w_2) + 4 w_2 \\ \frac{5}{2} x (w_1 + \frac{5}{2} w_2) + 4 w_2 \end{pmatrix} \frac{1}{\|\mathbf{w}\|^2} \mathbf{w} \end{align*}
